window.kbPageData["views/entry/k-07f734b3a96465ad"] = {"key":"entry/k-07f734b3a96465ad","state":{"route":"entry/k-07f734b3a96465ad"},"node":{"id":"k-07f734b3a96465ad","mode":"k","title":"活化石","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["活化石指缺少现存相似类群的遗迹生物"],"qs":["江苏 2023 A类 行测#66"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"活化石通常指延续至今、起源古老且保留若干祖先形态特征的生物或类群。部分释义强调缺少现存近似种，学术用法也涵盖仍有少数现存物种的古老类群。","review":{"definition":"活化石通常指延续至今、起源古老且保留若干祖先形态特征的生物或类群。部分释义强调缺少现存近似种，学术用法也涵盖仍有少数现存物种的古老类群。","explanation":"D项的“活化石”借用“化石”来称呼现生生物，题干的“元宇宙”也借用“宇宙”来命名数字虚拟空间，两组复合词都指向与原词类别不同的对象。C项的“云计算”仍属于计算方式，因而D更贴合题干关系。解析中“没有其他现存的相似物种”属于较窄的释义，判断本题只需区分现生生物和古生物遗存。","references":[{"source":"web-2348e6fc2c532db2","location":"“活化石”词目，释义","quote":"沒有現存的近似種"},{"source":"web-458e1db467ff8c70","location":"Introduction，列举鲎类等典型例子的段落","quote":"all have few surviving species"}],"evidence":"活化石又称遗迹生物","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 A类 行测#66":{"paper":"江苏 2023 A类 行测","n":66,"mod":"判断推理","src":["22304fe4c340e19d7902.pdf",12],"asrc":["be17f9afe070cf13a0fb.pdf",19],"card":"01120ffa29ec82a8b06fa942","links":[{"id":"k-07f734b3a96465ad","role":"解题依据","why":"遗迹生物的含义用于区分活化石与化石的所指。"}]}},"terms":{},"references":{"web-2348e6fc2c532db2":{"name":"教育部《重編國語辭典修訂本》","url":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=84113&la=0&powerMode=0"},"web-458e1db467ff8c70":{"name":"《Quantifying the living fossil concept》","url":"https://palaeo-electronica.org/content/2018/2194-quantifying-the-living-fossil"}},"topics":[],"units":{"k-07f734b3a96465ad":[["江苏 2023 A类 行测#66"]]}};
